insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'متى يكون mixin مناسبًا لمشاركة سلوك في Dart؟', 'mixin مناسب لسلوك أفقي صغير يمكن تركيبه على classes متعددة من غير ادعاء علاقة وراثة، مع تحديد on عندما يحتاج نوعًا أساسيًا معينًا.', 'المـixin يضيف implementation إلى class عبر with، ويمنع تكرار سلوك مشترك لا يمثل is-a relationship. اجعله مركزًا ومحدودًا، واستخدم on فقط عندما يعتمد السلوك فعلًا على contract محدد؛ mixin ضخم يتحول إلى base class مخفي.', 'mixin Loggable {
  void log(String message) => print(message);
}

class ApiClient with Loggable {}', '["استخدام mixin لتجميع state وعلاقات كثيرة غير مترابطة.","نسيان أن ترتيب mixins قد يؤثر على override resolution."]'::jsonb, '["ما الفرق بين mixin وextension method؟"]'::jsonb, '[{"title":"Dart language — Mixins","url":"https://dart.dev/language/mixins"}]'::jsonb from public.question_revisions r where r.question_id = 'oop-006' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
