insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تعرّف equality صحيحة لـ value object في Dart؟', 'override == وhashCode معًا باستخدام نفس الحقول التي تحدد الهوية المنطقية، ولا تغيّر هذه الحقول أثناء استخدام object كمفتاح.', 'الـSet والـMap يعتمدان على اتساق == مع hashCode: لو كائنان متساويان يجب أن يكون لهما hashCode واحد. قارن الأنواع والحقول المهمة فقط، وحافظ على immutability للحقول التي تدخل في الهوية حتى لا يصبح المفتاح غير قابل للوصول.', 'final class Point {
  const Point(this.x, this.y);
  final int x;
  final int y;

  @override bool operator ==(Object other) =>
      other is Point && other.x == x && other.y == y;
  @override int get hashCode => Object.hash(x, y);
}', '["override == من غير hashCode.","استخدام mutable fields في hashCode ثم تعديلها داخل Set أو Map."]'::jsonb, '["لماذا يجب فحص runtime type قبل مقارنة الحقول؟"]'::jsonb, '[{"title":"Dart API — Object ==","url":"https://api.dart.dev/dart-core/Object/operator_equals.html"},{"title":"Dart API — Object.hashCode","url":"https://api.dart.dev/dart-core/Object/hashCode.html"}]'::jsonb from public.question_revisions r where r.question_id = 'oop-007' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'oop-007' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تعرّف equality صحيحة لـ value object في Dart؟' or l.short_answer is distinct from 'override == وhashCode معًا باستخدام نفس الحقول التي تحدد الهوية المنطقية، ولا تغيّر هذه الحقول أثناء استخدام object كمفتاح.' or l.explanation is distinct from 'الـSet والـMap يعتمدان على اتساق == مع hashCode: لو كائنان متساويان يجب أن يكون لهما hashCode واحد. قارن الأنواع والحقول المهمة فقط، وحافظ على immutability للحقول التي تدخل في الهوية حتى لا يصبح المفتاح غير قابل للوصول.' or l.code_example is distinct from 'final class Point {
