      other is Point && other.x == x && other.y == y;
  @override int get hashCode => Object.hash(x, y);
}' or l.common_mistakes is distinct from '["override == من غير hashCode.","استخدام mutable fields في hashCode ثم تعديلها داخل Set أو Map."]'::jsonb or l.follow_up_questions is distinct from '["لماذا يجب فحص runtime type قبل مقارنة الحقول؟"]'::jsonb or l.sources is distinct from '[{"title":"Dart API — Object ==","url":"https://api.dart.dev/dart-core/Object/operator_equals.html"},{"title":"Dart API — Object.hashCode","url":"https://api.dart.dev/dart-core/Object/hashCode.html"}]'::jsonb)) then raise exception 'Question oop-007 ar content changed; create a new revision before seeding'; end if; end $$;
