insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إيه فوائد immutable value objects في تطبيق Flutter؟', 'القيم غير القابلة للتعديل أسهل في المقارنة والاختبار وتتبع تغييرات الواجهة، وتقلل الآثار الجانبية بين أجزاء التطبيق.', 'اجعل الحقول final، وفّر constructor واضحًا، وأعد instance جديدة عند التغيير بدل تعديل القديمة. هذا يجعل state transitions صريحة ويقلل مفاجآت rebuilds، لكن لا تحوّل كل object إلى immutable بلا حاجة؛ الصور والموارد ذات lifecycle مختلف.', null, '["تجميد reference مع إبقاء List داخلية قابلة للتعديل.","اعتبار إنشاء نسخة جديدة حلًا لمشكلة أداء قبل القياس."]'::jsonb, '["كيف تحمي collection داخل value object من التعديل الخارجي؟"]'::jsonb, '[{"title":"Dart Blog — An intro to immutability","url":"https://dart.dev/blog/an-intro-to-immutability-with-dart"}]'::jsonb from public.question_revisions r where r.question_id = 'oop-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'oop-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إيه فوائد immutable value objects في تطبيق Flutter؟' or l.short_answer is distinct from 'القيم غير القابلة للتعديل أسهل في المقارنة والاختبار وتتبع تغييرات الواجهة، وتقلل الآثار الجانبية بين أجزاء التطبيق.' or l.explanation is distinct from 'اجعل الحقول final، وفّر constructor واضحًا، وأعد instance جديدة عند التغيير بدل تعديل القديمة. هذا يجعل state transitions صريحة ويقلل مفاجآت rebuilds، لكن لا تحوّل كل object إلى immutable بلا حاجة؛ الصور والموارد ذات lifecycle مختلف.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تجميد reference مع إبقاء List داخلية قابلة للتعديل.","اعتبار إنشاء نسخة جديدة حلًا لمشكلة أداء قبل القياس."]'::jsonb or l.follow_up_questions is distinct from '["كيف تحمي collection داخل value object من التعديل الخارجي؟"]'::jsonb or l.sources is distinct from '[{"title":"Dart Blog — An intro to immutability","url":"https://dart.dev/blog/an-intro-to-immutability-with-dart"}]'::jsonb)) then raise exception 'Question oop-008 ar content changed; create a new revision before seeding'; end if; end $$;
