insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('solid-001', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي نطبق Single Responsibility Principle في شاشة Flutter؟', 'خلي كل وحدة تملك سبب تغيير واحد؛ الشاشة تنسق العرض، والخدمات أو controllers تملك منطق البيانات المناسب لها.', 'SRP لا يعني أن كل class يحتوي ميثود واحدة. اسأل: هل تغييرات تصميم الواجهة وتغييرات API ستجبر نفس الملف على التعديل؟ فصل orchestration عن data access وعن presentation يجعل الكود أوضح وأسهل في الاختبار من غير طبقات شكلية.', null, '["تقسيم كل سطر إلى class جديد بلا سبب تغيير حقيقي.","ترك parsing وطلبات الشبكة داخل build method."]'::jsonb, '["ما العلامة التي تقول إن الفصل زاد عن حاجته؟"]'::jsonb, '[{"title":"Flutter docs — App architecture","url":"https://docs.flutter.dev/app-architecture"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb from public.question_revisions r where r.question_id = 'solid-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'solid-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي نطبق Single Responsibility Principle في شاشة Flutter؟' or l.short_answer is distinct from 'خلي كل وحدة تملك سبب تغيير واحد؛ الشاشة تنسق العرض، والخدمات أو controllers تملك منطق البيانات المناسب لها.' or l.explanation is distinct from 'SRP لا يعني أن كل class يحتوي ميثود واحدة. اسأل: هل تغييرات تصميم الواجهة وتغييرات API ستجبر نفس الملف على التعديل؟ فصل orchestration عن data access وعن presentation يجعل الكود أوضح وأسهل في الاختبار من غير طبقات شكلية.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["تقسيم كل سطر إلى class جديد بلا سبب تغيير حقيقي.","ترك parsing وطلبات الشبكة داخل build method."]'::jsonb or l.follow_up_questions is distinct from '["ما العلامة التي تقول إن الفصل زاد عن حاجته؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — App architecture","url":"https://docs.flutter.dev/app-architecture"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb)) then raise exception 'Question solid-001 ar content changed; create a new revision before seeding'; end if; end $$;
