insert into public.interview_questions (id, slug, track_id, difficulty) values ('solid-002', 'open-closed-principle-for-renderers', 'flutter', 'Mid') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
