insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'كيف يساعد Open/Closed Principle عند إضافة أنواع UI جديدة؟', 'صمّم نقطة امتداد تضيف implementation جديدة من غير تعديل منطق قديم ومستقر، لكن لا تبنِ abstraction قبل ظهور variation حقيقي.', 'بدل if أو switch يتضخم مع كل نوع، يمكن تعريف contract للمصدر أو renderer وإضافة implementation جديدة. OCP ليس منع كل تعديل؛ الكود نفسه يجب أن يتغير عندما يتغير المتطلب، والفائدة تظهر عندما يكون محور التغيير معروفًا ومكررًا.', 'abstract interface class CardRenderer {
  String render();
}

String buildCard(CardRenderer renderer) => renderer.render();', '["إنشاء factory وinterface لفرع واحد لا يتغير.","إخفاء switch داخل abstraction من غير تقليل تكلفة التغيير."]'::jsonb, '["إمتى يكون switch الواضح أفضل من polymorphism؟"]'::jsonb, '[{"title":"Flutter docs — Design patterns","url":"https://docs.flutter.dev/app-architecture/design-patterns"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb from public.question_revisions r where r.question_id = 'solid-002' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'solid-002' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'كيف يساعد Open/Closed Principle عند إضافة أنواع UI جديدة؟' or l.short_answer is distinct from 'صمّم نقطة امتداد تضيف implementation جديدة من غير تعديل منطق قديم ومستقر، لكن لا تبنِ abstraction قبل ظهور variation حقيقي.' or l.explanation is distinct from 'بدل if أو switch يتضخم مع كل نوع، يمكن تعريف contract للمصدر أو renderer وإضافة implementation جديدة. OCP ليس منع كل تعديل؛ الكود نفسه يجب أن يتغير عندما يتغير المتطلب، والفائدة تظهر عندما يكون محور التغيير معروفًا ومكررًا.' or l.code_example is distinct from 'abstract interface class CardRenderer {
  String render();
}

String buildCard(CardRenderer renderer) => renderer.render();' or l.common_mistakes is distinct from '["إنشاء factory وinterface لفرع واحد لا يتغير.","إخفاء switch داخل abstraction من غير تقليل تكلفة التغيير."]'::jsonb or l.follow_up_questions is distinct from '["إمتى يكون switch الواضح أفضل من polymorphism؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Design patterns","url":"https://docs.flutter.dev/app-architecture/design-patterns"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb)) then raise exception 'Question solid-002 ar content changed; create a new revision before seeding'; end if; end $$;
