insert into public.question_revisions (question_id, revision_number, status, reviewed_at) values ('solid-003', 1, 'draft', '2026-08-30') on conflict (question_id, revision_number) do nothing;
insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'ما معنى Liskov Substitution Principle في كود Dart؟', 'أي subtype يجب أن يحل محل الـbase contract من غير كسر توقعات المستهلك في النتائج أو القيود أو الأخطاء.', 'لو implementation ترمي UnsupportedError لميثود يفرضها base interface أو تقبل مدخلات أضيق من العقد، فهي غالبًا ليست subtype صالحًا. أصلح العقد ليعبّر عن القدرات الحقيقية أو استخدم interfaces أصغر بدل إجبار كل implementation على سلوك لا يملكه.', null, '["اعتبار inheritance صحيحًا لمجرد أن الكود يترجم.","إرجاع null أو خطأ مفاجئ بدل contract متوقع."]'::jsonb, '["كيف تكشف اختبارًا أن implementation كسرت LSP؟"]'::jsonb, '[{"title":"Dart language — Class modifiers","url":"https://dart.dev/language/class-modifiers"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb from public.question_revisions r where r.question_id = 'solid-003' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'solid-003' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'ما معنى Liskov Substitution Principle في كود Dart؟' or l.short_answer is distinct from 'أي subtype يجب أن يحل محل الـbase contract من غير كسر توقعات المستهلك في النتائج أو القيود أو الأخطاء.' or l.explanation is distinct from 'لو implementation ترمي UnsupportedError لميثود يفرضها base interface أو تقبل مدخلات أضيق من العقد، فهي غالبًا ليست subtype صالحًا. أصلح العقد ليعبّر عن القدرات الحقيقية أو استخدم interfaces أصغر بدل إجبار كل implementation على سلوك لا يملكه.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اعتبار inheritance صحيحًا لمجرد أن الكود يترجم.","إرجاع null أو خطأ مفاجئ بدل contract متوقع."]'::jsonb or l.follow_up_questions is distinct from '["كيف تكشف اختبارًا أن implementation كسرت LSP؟"]'::jsonb or l.sources is distinct from '[{"title":"Dart language — Class modifiers","url":"https://dart.dev/language/class-modifiers"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb)) then raise exception 'Question solid-003 ar content changed; create a new revision before seeding'; end if; end $$;
