insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تبدأ refactor لكود Flutter قديم باستخدام SOLID بأمان؟', 'ابدأ بسلوك قابل للملاحظة واختبار صغير، حدد أكثر سبب تغيير مؤلم، ثم افصل حدًا واحدًا مع إبقاء السلوك كما هو.', 'لا تعِد كتابة الشاشة كلها دفعة واحدة. أضف characterization test، افصل طلب الشبكة أو parsing خلف contract، ثم انقل المسؤولية تدريجيًا. كل خطوة يجب أن تقلل coupling أو تحسن الاختبار، وإلا ارجع لأبسط شكل.', null, '["دمج refactor شامل مع تغيير سلوك يصعب مراجعته.","اختيار abstraction قبل فهم السلوك الحالي والقيود."]'::jsonb, '["ما أول seam تختاره لاختبار شاشة تعتمد على API؟"]'::jsonb, '[{"title":"Flutter docs — App architecture","url":"https://docs.flutter.dev/app-architecture"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb from public.question_revisions r where r.question_id = 'solid-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'solid-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تبدأ refactor لكود Flutter قديم باستخدام SOLID بأمان؟' or l.short_answer is distinct from 'ابدأ بسلوك قابل للملاحظة واختبار صغير، حدد أكثر سبب تغيير مؤلم، ثم افصل حدًا واحدًا مع إبقاء السلوك كما هو.' or l.explanation is distinct from 'لا تعِد كتابة الشاشة كلها دفعة واحدة. أضف characterization test، افصل طلب الشبكة أو parsing خلف contract، ثم انقل المسؤولية تدريجيًا. كل خطوة يجب أن تقلل coupling أو تحسن الاختبار، وإلا ارجع لأبسط شكل.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["دمج refactor شامل مع تغيير سلوك يصعب مراجعته.","اختيار abstraction قبل فهم السلوك الحالي والقيود."]'::jsonb or l.follow_up_questions is distinct from '["ما أول seam تختاره لاختبار شاشة تعتمد على API؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — App architecture","url":"https://docs.flutter.dev/app-architecture"},{"title":"Robert C. Martin — Solid Relevance","url":"https://blog.cleancoder.com/uncle-bob/2020/10/18/Solid-Relevance.html"}]'::jsonb)) then raise exception 'Question solid-008 ar content changed; create a new revision before seeding'; end if; end $$;
