insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إيه الحالات الأساسية في lifecycle بتاع تطبيق Flutter؟', 'AppLifecycleListener يتابع حالات مثل resumed وinactive وhidden وpaused وdetached، مع اختلاف الانتقالات حسب المنصة.', 'استخدم lifecycle لإيقاف عمل مؤقت أو حفظ state عند انتقال التطبيق للخلفية، لكن لا تفترض أن كل منصة ترسل نفس التسلسل أو أن callback واحد يضمن اكتمال الحفظ. اربط listener بعمر الشاشة أو التطبيق ونظّفه عند الانتهاء.', null, '["اعتبار paused هو الحالة الوحيدة المهمة.","ترك listener يعمل بعد dispose أو الاعتماد على callback واحد لحفظ بيانات حرجة."]'::jsonb, '["متى تستخدم AppLifecycleListener بدل WidgetsBindingObserver؟"]'::jsonb, '[{"title":"Flutter API — AppLifecycleListener","url":"https://api.flutter.dev/flutter/widgets/AppLifecycleListener-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'fundamentals-008' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'fundamentals-008' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إيه الحالات الأساسية في lifecycle بتاع تطبيق Flutter؟' or l.short_answer is distinct from 'AppLifecycleListener يتابع حالات مثل resumed وinactive وhidden وpaused وdetached، مع اختلاف الانتقالات حسب المنصة.' or l.explanation is distinct from 'استخدم lifecycle لإيقاف عمل مؤقت أو حفظ state عند انتقال التطبيق للخلفية، لكن لا تفترض أن كل منصة ترسل نفس التسلسل أو أن callback واحد يضمن اكتمال الحفظ. اربط listener بعمر الشاشة أو التطبيق ونظّفه عند الانتهاء.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["اعتبار paused هو الحالة الوحيدة المهمة.","ترك listener يعمل بعد dispose أو الاعتماد على callback واحد لحفظ بيانات حرجة."]'::jsonb or l.follow_up_questions is distinct from '["متى تستخدم AppLifecycleListener بدل WidgetsBindingObserver؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter API — AppLifecycleListener","url":"https://api.flutter.dev/flutter/widgets/AppLifecycleListener-class.html"}]'::jsonb)) then raise exception 'Question fundamentals-008 ar content changed; create a new revision before seeding'; end if; end $$;
