insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إزاي تصمم local persistence قابلة للاختبار ومقاومة لفشل التخزين؟', 'اعزل storage خلف contract صغير، عالج غياب البيانات وأخطاء القراءة والكتابة صراحةً، واختبر serialization والترقية بعيدًا عن UI.', 'المستخدم قد يملك نسخة قديمة أو ملفًا تالفًا أو مساحة قرص ممتلئة، لذلك لا تحول exception إلى data فارغة بصمت. اجعل format وdefaults وschema version جزءًا من boundary، واستبدل implementation الحقيقية بـin-memory fake في الاختبار. لا تخلط persistence الدائم مع restoration المؤقت أو cache الذي يمكن إعادة بنائه.', null, '["ابتلاع كل storage errors ثم عرض نجاح كاذب.","ربط الشاشة مباشرة بـpackage أو database API.","اعتبار cache وبيانات المستخدم الدائمة نفس مستوى الأهمية."]'::jsonb, '["كيف تميّز بين بيانات stale وبيانات لا يمكن استعادتها؟"]'::jsonb, '[{"title":"Flutter cookbook — Store key-value data on disk","url":"https://docs.flutter.dev/cookbook/persistence/key-value"},{"title":"Flutter cookbook — Persist data with SQLite","url":"https://docs.flutter.dev/cookbook/persistence/sqlite"},{"title":"Flutter docs — App architecture guide","url":"https://docs.flutter.dev/app-architecture/guide"},{"title":"Dart API — File","url":"https://api.dart.dev/dart-io/File-class.html"}]'::jsonb from public.question_revisions r where r.question_id = 'storage-005' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'storage-005' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إزاي تصمم local persistence قابلة للاختبار ومقاومة لفشل التخزين؟' or l.short_answer is distinct from 'اعزل storage خلف contract صغير، عالج غياب البيانات وأخطاء القراءة والكتابة صراحةً، واختبر serialization والترقية بعيدًا عن UI.' or l.explanation is distinct from 'المستخدم قد يملك نسخة قديمة أو ملفًا تالفًا أو مساحة قرص ممتلئة، لذلك لا تحول exception إلى data فارغة بصمت. اجعل format وdefaults وschema version جزءًا من boundary، واستبدل implementation الحقيقية بـin-memory fake في الاختبار. لا تخلط persistence الدائم مع restoration المؤقت أو cache الذي يمكن إعادة بنائه.' or l.code_example is distinct from null or l.common_mistakes is distinct from '["ابتلاع كل storage errors ثم عرض نجاح كاذب.","ربط الشاشة مباشرة بـpackage أو database API.","اعتبار cache وبيانات المستخدم الدائمة نفس مستوى الأهمية."]'::jsonb or l.follow_up_questions is distinct from '["كيف تميّز بين بيانات stale وبيانات لا يمكن استعادتها؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter cookbook — Store key-value data on disk","url":"https://docs.flutter.dev/cookbook/persistence/key-value"},{"title":"Flutter cookbook — Persist data with SQLite","url":"https://docs.flutter.dev/cookbook/persistence/sqlite"},{"title":"Flutter docs — App architecture guide","url":"https://docs.flutter.dev/app-architecture/guide"},{"title":"Dart API — File","url":"https://api.dart.dev/dart-io/File-class.html"}]'::jsonb)) then raise exception 'Question storage-005 ar content changed; create a new revision before seeding'; end if; end $$;
