insert into public.question_revision_locales (revision_id, locale, question, short_answer, explanation, code_example, common_mistakes, follow_up_questions, sources) select r.id, 'ar', 'إيه دور platform channels وإزاي تحافظ على boundary واضحة مع native code؟', 'Platform channel تنقل رسائل asynchronous بين Dart وكود المنصة مثل Kotlin أو Swift؛ ضع contract وadapter بعيدًا عن Widgets وعرّف الأخطاء والأنواع بوضوح.', 'عندما لا تكفي APIs المشتركة أو plugin جاهز، يرسل جانب Flutter method أو message عبر channel باسم وcodec متفق عليه، ويرد host بنتيجة أو خطأ. اجعل أسماء methods والـpayload versioned ومحدودة، وحوّل نتيجة native إلى model أو error domain داخل boundary؛ لا تنشر MethodChannel في كل شاشة ولا تفترض أن كل منصة تدعم السلوك نفسه.', 'const channel = MethodChannel("com.example.device");
final value = await channel.invokeMethod<int>("readValue");', '["خلط channel calls داخل build أو presentation logic.","عدم تطابق channel name أو payload بين Dart والـhost.","نسيان platform exceptions أو اختلاف capabilities بين المنصات."]'::jsonb, '["متى يكون Pigeon أنسب من كتابة MethodChannel يدويًا؟"]'::jsonb, '[{"title":"Flutter docs — Writing custom platform-specific code","url":"https://docs.flutter.dev/platform-integration/platform-channels"}]'::jsonb from public.question_revisions r where r.question_id = 'platform-001' and r.revision_number = 1 on conflict (revision_id, locale) do nothing;
do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'platform-001' and r.revision_number = 1 and l.locale = 'ar' and (l.question is distinct from 'إيه دور platform channels وإزاي تحافظ على boundary واضحة مع native code؟' or l.short_answer is distinct from 'Platform channel تنقل رسائل asynchronous بين Dart وكود المنصة مثل Kotlin أو Swift؛ ضع contract وadapter بعيدًا عن Widgets وعرّف الأخطاء والأنواع بوضوح.' or l.explanation is distinct from 'عندما لا تكفي APIs المشتركة أو plugin جاهز، يرسل جانب Flutter method أو message عبر channel باسم وcodec متفق عليه، ويرد host بنتيجة أو خطأ. اجعل أسماء methods والـpayload versioned ومحدودة، وحوّل نتيجة native إلى model أو error domain داخل boundary؛ لا تنشر MethodChannel في كل شاشة ولا تفترض أن كل منصة تدعم السلوك نفسه.' or l.code_example is distinct from 'const channel = MethodChannel("com.example.device");
final value = await channel.invokeMethod<int>("readValue");' or l.common_mistakes is distinct from '["خلط channel calls داخل build أو presentation logic.","عدم تطابق channel name أو payload بين Dart والـhost.","نسيان platform exceptions أو اختلاف capabilities بين المنصات."]'::jsonb or l.follow_up_questions is distinct from '["متى يكون Pigeon أنسب من كتابة MethodChannel يدويًا؟"]'::jsonb or l.sources is distinct from '[{"title":"Flutter docs — Writing custom platform-specific code","url":"https://docs.flutter.dev/platform-integration/platform-channels"}]'::jsonb)) then raise exception 'Question platform-001 ar content changed; create a new revision before seeding'; end if; end $$;
