do $$ begin if exists (select 1 from public.question_revision_locales l join public.question_revisions r on r.id = l.revision_id where r.question_id = 'state-002' and r.revision_number = 1 and l.locale = 'en' and (l.question is distinct from 'What should a Flutter developer know about Lifting State Up In Flutter?' or l.short_answer is distinct from 'This question checks the core Lifting State Up In Flutter concept and how to use it safely in Dart and Flutter.' or l.explanation is distinct from 'Explain Lifting State Up In Flutter with its trade-offs, practical use cases, and the boundaries that keep the implementation maintainable.' or l.code_example is distinct from 'class Parent extends StatefulWidget {
