insert into public.interview_questions (id, slug, track_id, difficulty) values ('net-002', 'json-serialization-and-typed-models', 'flutter', 'Junior') on conflict (id) do update set slug = excluded.slug, track_id = excluded.track_id, difficulty = excluded.difficulty;
